<div class="d-flex flex-wrap justify-content-between gap-3 mb-4"><div><a class="small" href="<?= site_url('tickets') ?>">← Tickets</a><h1 class="h3 mt-2 mb-1"><?= esc($ticket['subject']) ?></h1><div class="text-secondary"><?= esc($ticket['ticket_number']) ?> · <?= esc($ticket['category_name']) ?> · <?= esc($ticket['created_at']) ?></div></div><div><span class="badge text-bg-secondary"><?= esc($ticket['status']) ?></span> <span class="badge text-bg-info"><?= esc($ticket['priority']) ?></span></div></div>
<div class="row g-3"><div class="col-lg-8"><div class="card mb-3"><div class="card-header">Description</div><div class="card-body ticket-description"><?= esc($ticket['description']) ?></div></div>
<div class="card mb-3"><div class="card-header">Comments</div><div class="card-body"><?php foreach ($comments as $comment): ?><article class="border-bottom pb-3 mb-3"><div class="d-flex justify-content-between"><strong><?= esc($comment['name']) ?></strong><time class="text-secondary small"><?= esc($comment['created_at']) ?></time></div><p class="mt-2 mb-2 ticket-description"><?= esc($comment['body']) ?></p><?php if ((int) $comment['user_id'] === (int) $user['id'] && $ticket['status'] !== 'Closed'): ?><details><summary class="small">Edit comment</summary><form method="post" action="<?= site_url('tickets/' . $ticket['id'] . '/comments/' . $comment['id'] . '/edit') ?>" class="mt-2"><?= csrf_field() ?><textarea class="form-control mb-2" name="body" maxlength="5000" required><?= esc($comment['body']) ?></textarea><button class="btn btn-sm btn-outline-primary">Save</button></form><form method="post" action="<?= site_url('tickets/' . $ticket['id'] . '/comments/' . $comment['id'] . '/delete') ?>" class="d-inline"><?= csrf_field() ?><button class="btn btn-sm btn-outline-danger">Delete</button></form></details><?php endif ?></article><?php endforeach ?><?php if (! $comments): ?><p class="text-secondary">No comments yet.</p><?php endif ?><?php if ($ticket['status'] !== 'Closed'): ?><form method="post" action="<?= site_url('tickets/' . $ticket['id'] . '/comments') ?>"><?= csrf_field() ?><label class="form-label" for="comment">Add a comment</label><textarea class="form-control mb-2" id="comment" name="body" rows="3" maxlength="5000" required></textarea><button class="btn btn-primary">Post comment</button></form><?php endif ?></div></div>
<div class="card"><div class="card-header">Attachments</div><div class="card-body"><ul class="list-group list-group-flush mb-3"><?php foreach ($attachments as $attachment): ?><li class="list-group-item d-flex justify-content-between align-items-center px-0"><a href="<?= site_url('attachments/' . $attachment['id']) ?>"><?= esc($attachment['original_name']) ?></a><span class="d-flex align-items-center gap-2"><span class="small text-secondary"><?= number_format((int) $attachment['size_bytes'] / 1024, 0) ?> KB</span><?php if ((int) $attachment['user_id'] === (int) $user['id'] && $ticket['status'] !== 'Closed'): ?><form method="post" action="<?= site_url('attachments/' . $attachment['id'] . '/delete') ?>"><?= csrf_field() ?><button class="btn btn-sm btn-outline-danger">Delete</button></form><?php endif ?></span></li><?php endforeach ?></ul><?php if ($ticket['status'] !== 'Closed' && count($attachments) < 3): ?><form method="post" enctype="multipart/form-data" action="<?= site_url('tickets/' . $ticket['id'] . '/attachments') ?>"><?= csrf_field() ?><label class="form-label" for="attachment">Upload JPG, PNG, or PDF (max 2 MB)</label><div class="input-group"><input class="form-control" type="file" id="attachment" name="attachment" accept=".jpg,.jpeg,.png,.pdf" required><button class="btn btn-outline-primary">Upload</button></div></form><?php endif ?></div></div></div>
<div class="col-lg-4"><div class="card mb-3"><div class="card-header">Ticket details</div><div class="card-body"><dl class="mb-0"><dt>Created by</dt><dd><?= esc($ticket['creator_name']) ?></dd><dt>Assigned to</dt><dd><?= esc($ticket['assignee_name'] ?? 'Unassigned') ?></dd><dt>Updated</dt><dd><?= esc($ticket['updated_at']) ?></dd></dl><a class="btn btn-sm btn-outline-secondary" href="<?= site_url('tickets/' . $ticket['id'] . '/history') ?>">View history</a></div></div>
<?php if ($user['role'] === 'IT Manager' && in_array($ticket['status'], ['Open', 'In Progress'], true)): ?><div class="card mb-3"><div class="card-header">Assign IT Support</div><div class="card-body"><form method="post" action="<?= site_url('tickets/' . $ticket['id'] . '/assignment') ?>"><?= csrf_field() ?><label class="form-label" for="support_id">Active support user</label><select class="form-select mb-3" id="support_id" name="support_id" required><option value="">Choose…</option><?php foreach ($support as $person): ?><option value="<?= (int) $person['id'] ?>" <?= (int) $ticket['assigned_to'] === (int) $person['id'] ? 'selected' : '' ?>><?= esc($person['name']) ?></option><?php endforeach ?></select><button class="btn btn-primary">Assign / reassign</button></form></div></div><?php endif ?>
<?php if ($ticket['status'] !== 'Closed'): ?><div class="card mb-3"><div class="card-header">Update status</div><div class="card-body"><?php $nextStatuses = $user['role'] === 'IT Support' ? (['Open' => 'In Progress', 'In Progress' => 'Resolved'][$ticket['status']] ?? null) : ($user['role'] === 'Employee' && $ticket['status'] === 'Resolved' ? ['Closed', 'In Progress'] : null); ?><?php if ($nextStatuses): ?><form method="post" action="<?= site_url('tickets/' . $ticket['id'] . '/status') ?>"><?= csrf_field() ?><label class="form-label" for="status">New status</label><select class="form-select mb-3" id="status" name="status"><?php foreach ((array) $nextStatuses as $status): ?><option><?= esc($status) ?></option><?php endforeach ?></select><button class="btn btn-primary">Update status</button></form><?php else: ?><span class="text-secondary small">Status changes are unavailable for this role or state.</span><?php endif ?></div></div><?php endif ?>
<?php if ($user['role'] === 'Employee' && $ticket['status'] === 'Open'): ?><div class="d-flex gap-2"><a class="btn btn-outline-primary" href="<?= site_url('tickets/' . $ticket['id'] . '/edit') ?>">Edit ticket</a><form method="post" action="<?= site_url('tickets/' . $ticket['id'] . '/delete') ?>"><?= csrf_field() ?><button class="btn btn-outline-danger">Delete ticket</button></form></div><?php endif ?></div></div>
